import{_ as i,c as o,a2 as t,o as e}from"./chunks/framework.CO0qOYmW.js";const T=JSON.parse('{"title":"网络面试题","description":"","frontmatter":{"title":"网络面试题","category":"面试题","excerpt":"URL 解析 ：检查和纠错、转换， 检查URL地址是否完整，不完整需要补全， 检查URL是否存在，是否可以访问，是否存在重定向。 转换URL，将其转换为标准格式 Ascii码。 DNS 查询 ：DNS 服务器解析域名，将域名解析为 IP 地..."},"headers":[],"relativePath":"interview/09-network.md","filePath":"interview/09-network.md","lastUpdated":1773591891000}'),a={name:"interview/09-network.md"};function c(s,l,r,p,u,d){return e(),o("div",null,l[0]||(l[0]=[t('<h1 id="网络面试题" tabindex="-1">网络面试题 <a class="header-anchor" href="#网络面试题" aria-label="Permalink to &quot;网络面试题&quot;">​</a></h1><h2 id="_1-地址栏输入url回车之后发生了什么" tabindex="-1">1. 地址栏输入URL回车之后发生了什么？ <a class="header-anchor" href="#_1-地址栏输入url回车之后发生了什么" aria-label="Permalink to &quot;1. 地址栏输入URL回车之后发生了什么？&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">详细解释</p><ol><li><p>URL 解析 ：检查和纠错、转换，</p><ul><li>检查URL地址是否完整，不完整需要补全，</li><li>检查URL是否存在，是否可以访问，是否存在重定向。</li><li>转换URL，将其转换为标准格式 <code>Ascii码</code>。</li></ul></li><li><p>DNS 查询 ：DNS 服务器解析域名，将域名解析为 IP 地址。</p></li><li><p>建立 TCP 连接 ：TCP 三次握手建立 TCP 连接。</p><ul><li>第一次握手：客户端发送 SYN 报文，服务器接收到 SYN 报文，并发送 SYN+ACK 报文。</li><li>第二次握手：服务器发送 ACK 报文，客户端接收到 ACK 报文，并发送 ACK 报文。</li><li>第三次握手：客户端发送 ACK 报文，服务器接收到 ACK 报文，连接建立成功。</li><li>SSL/TLS 握手：如果是 HTTPS 协议，还需要进行 SSL/TLS 握手。</li></ul></li><li><p>准备请求：准备请求头：Cookie + ...</p></li><li><p>发送 HTTP 请求 ： 客户端向服务器发送 HTTP 请求，请求方式为 GET。</p></li><li><p>服务器处理请求 ：服务器接收到 HTTP 请求，并从数据库或其他存储介质中获取请求资源。</p></li><li><p>服务器返回响应 ：服务器将请求资源返回给客户端，并发送 HTTP 响应。</p></li><li><p>客户端接收响应头 ：客户端接收到 HTTP 响应，并显示响应内容。</p></li><li><p>客户端处理响应头 ：客户端处理 HTTP 响应头，如设置 Cookie 、处理content-type、缓存、状态码、connection：keep-alive保活等。</p></li><li><p>客户端收响应体 ：客户端如果收到HTML，需要一边接收一边渲染，如果收到其他类型文件，则直接显示。</p></li><li><p>渲染：</p><ul><li><ol><li>解析HTMl文档（预处理线程，资源加载、资源描述符：async / defer/ prefetch/ preload ）：render 树+ CSSOM 树 生成</li></ol></li><li><ol start="2"><li>样式计算</li></ol></li><li><ol start="3"><li>布局：生成渲染树，并计算布局（回流）</li></ol></li><li><ol start="4"><li>layer分层：将渲染树分层，并生成图层树</li></ol></li><li><ol start="5"><li><code>paint</code>绘制：将图层树绘制到屏幕上 ，主线程结束工作</li></ol></li><li><ol start="6"><li>合成：将图层合成到页面上，合成线程开始工作。</li></ol></li><li><ol start="7"><li>tiles分块：将合成结果分成小块，页面优先显示一部分。</li></ol></li><li><ol start="8"><li>栅格化</li></ol></li><li><ol start="9"><li>draw 绘制: 将渲染结果绘制到屏幕上。</li></ol></li></ul></li><li><p>根据情况决定是否断开连接：客户端接收完响应体后，再决定是否断开连接。</p></li><li><p>关闭 TCP 连接 ：TCP 四次挥手关闭 TCP 连接。</p><ul><li>第一次挥手：客户端发送 FIN 报文，服务器接收到 FIN 报文，并发送 ACK 报文。</li><li>第二次挥手：服务器发送 FIN 报文，客户端接收到 FIN 报文，并发送 ACK 报文。</li><li>第三次挥手：客户端发送 ACK 报文，服务器接收到 ACK 报文，连接关闭。</li><li>第四次挥手：服务器发送 ACK 报文，客户端接收到 ACK 报文，连接关闭。</li></ul></li></ol></div><h2 id="_2-什么是跨域" tabindex="-1">2. 什么是跨域 <a class="header-anchor" href="#_2-什么是跨域" aria-label="Permalink to &quot;2. 什么是跨域&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">详细解释</p><ul><li><p>跨域是一种<strong>浏览器的安全策略</strong>：浏览器出于安全考虑，对同源请求放行，对异源请求限制，这种限制规则称为同源策略。</p></li><li><p>同源：两个页面具有相同协议、域名、端口号。</p></li><li><p>同源请求：<strong>页面源</strong>向 <strong>同源目标源</strong> 发送请求获取资源的行为。</p></li><li><p>浏览器如何限制：</p><ul><li>对<code>标签</code>发出的跨域请求轻微限制。</li><li>对<code>AJAX</code>发出的跨域请求严格限制。浏览器会正常发送请求，服务器正常响应，浏览器会对跨域请求的响应进行校验。如果服务器响应头中没有<code>Access-Control-Allow-Origin</code>字段，浏览器会拦截响应。</li></ul></li><li><p>跨域解决方案：</p><ul><li>CORS(官方推荐)：跨源资源共享机制，是 W3C 标准，通过<code>服务器</code>设置响应头，允许跨域请求。</li><li>JSONP（老版本）：利用 <code>&lt;script&gt;</code> 标签的 <code>src</code> 属性，服务器响应数据时会运行一个函数，这个函数与前端的一个函数的名字相同，服务器响应这个函数时，浏览器会执行这个函数，并将数据作为参数传入。（缺陷：只支持 GET 请求）</li><li><code>Proxy</code>代理服务器: 浏览器向代理服务器进行数据请求，由代理服务器向目标服务器请求数据，然后返回给浏览器。</li></ul></li><li><p>CORS 将请求分为两类：</p><ul><li><p><strong>简单请求：</strong></p><ol><li>请求方法是 GET、HEAD、POST；</li><li>请求头没有特别的限制；</li><li><code>Content-Type</code> 仅限于 <code>application/x-www-form-urlencoded</code>、<code>multipart/form-data</code>、<code>text/plain</code>。</li></ol></li><li><p><strong>预检请求:</strong> 非简单请求。</p></li><li><p><strong>通过简单请求</strong>：浏览器会自动带上<code>Origin</code>:表示当前页面源。服务器通过<code>Access-Control-Allow-Origin</code>响应头来允许页面源 通过跨域请求。</p></li><li><p>**通过预检请求：**浏览器会先发送预检请求，预检请求的请求方法为<code>OPTIONS</code>，请求头中包含<code>Origin</code>（当前页面源）和<code>Access-Control-Request-Method</code>（请求方法）和<code>Access-Control-Request-Headers</code>（这次请求改动的哪些请求头），服务器通过返回的<code>Access-Control-Allow-Origin</code>、<code>Access-Control-Allow-Methods</code>、<code>Access-Control-Allow-Headers</code>、<code>Access-Control-Max-Age</code>（<strong>预检请求的有效期</strong>）响应头来允许页面源 通过跨域请求，并确定是否可以发送真实请求。</p></li></ul></li></ul></div><h2 id="_3-get和post的区别" tabindex="-1">3. GET和POST的区别 <a class="header-anchor" href="#_3-get和post的区别" aria-label="Permalink to &quot;3. GET和POST的区别&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">详细解释</p><p></p><ol><li><strong>语义</strong>（主要区别）：GET 通常用于获取或查询资源，而 POST 通常用于创建或修改资源。</li><li><strong>幂等</strong>：GET 请求是幂等的，即多次重复执行不会改变资源的状态，而 POST 请求是不幂等的，即每次执行可能会产生不同的结果或影响资源的状态。</li><li><strong>格式</strong>：GET 请求的参数通常放在 URL 中，形成查询字符串（querystring），而 POST 请求的参数通常放在请求体（body）中，可以有多种编码格式，如 application/x-www-form-urlencoded、multipart/form-data、application/json 等。GET 请求的 URL 长度受到浏览器和服务器的限制，而 POST 请求的 body 大小则没有明确的限制。不过，实际上 GET 请求也可以用 body 传输数据，只是并不推荐这样做，因为这样可能会导致一些兼容性或者语义上的问题。</li><li><strong>缓存</strong>：由于 GET 请求是幂等的，它可以被浏览器或其他中间节点（如代理、网关）缓存起来，以提高性能和效率。而 POST 请求则不适合被缓存，因为它可能有副作用，每次执行可能需要实时的响应。</li><li><strong>安全性</strong>：GET 请求和 POST 请求如果使用 HTTP 协议的话，那都不安全，因为 HTTP 协议本身是明文传输的，必须使用 HTTPS 协议来加密传输数据。另外，GET 请求相比 POST 请求更容易泄露敏感数据，因为 GET 请求的参数通常放在 URL 中。</li></ol></div><details class="details custom-block"><summary>粗略介绍</summary><div class="important custom-block github-alert"><p class="custom-block-title">区别</p><p></p><ul><li><strong>协议层面</strong><ul><li>只有语义的差别</li><li>HTTP报文由请求行、请求头、空行和请求体组成。</li></ul></li><li><strong>应用层面</strong></li><li>约定俗成的规范：往往会把一些请求（如<code>GET</code>）的请求体置空。（不是没有）</li></ul></div><div class="tip custom-block github-alert"><p class="custom-block-title">GET</p><p></p><ul><li>将请求的数据附加在 URL 后面，以查询字符串的形式出现，一般用于查询。</li><li>数据量有限制，通常不超过 2KB。</li><li>适合请求无状态的操作，如页面跳转、检索数据等</li></ul></div><div class="tip custom-block github-alert"><p class="custom-block-title">POST</p><p></p><ul><li>用于向服务器发送数据。它将数据存储在请求体中，不会出现在 URL 中。</li><li>数据量没有限制，适合请求有状态的操作，如登录、注册等。</li></ul></div></details><h2 id="_4-http状态码" tabindex="-1">4. HTTP状态码 <a class="header-anchor" href="#_4-http状态码" aria-label="Permalink to &quot;4. HTTP状态码&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">详细解释</p><p></p><ul><li>1xx：信息提示类，表示接收到请求，需要进一步处理。 <ul><li>100 Continue：客户端应当继续发送请求。</li><li>101 Switching Protocol：服务器切换协议。</li><li>102 Processing：由 WebDAV扩展的状态码，表示请求尚未完成。</li></ul></li><li>2xx：成功类，表示请求成功收到，理解并处理。 <ul><li>200 OK：请求成功,响应中包含请求的数据（网页、API 返回 JSON）。</li><li>201 Created：请求成功，且服务器创建了新的资源（POST 新建用户后返回）。</li><li>202 Accepted：服务器已接受请求，但未处理完成（异步任务）。</li><li>204 No Content：请求成功，但响应无内容（DELETE 删除资源后返回）。</li><li>206 Partial Content：服务器返回部分数据（用于分块下载或断点续传）。</li></ul></li><li>3xx：重定向类，表示需要进行附加操作以完成请求。 <ul><li>301 Moved Permanently：永久重定向，请求的资源已被分配新的</li><li>302 Found：临时重定向，请求的资源已被分配新的.（A/B 测试）</li><li>303 See Other：强制要求重定向后使用 GET 方法（常用于 POST 后跳转）。</li><li>304 Not Modified：客户端发送附带条件的请求，服务器端允许请求访问资源，但未满足条件。</li><li>307 Temporary Redirect：临时重定向，且保持原始 HTTP 方法。</li><li>308 Permanent Redirect：永久重定向，且保持原始 HTTP 方法。</li></ul></li><li>4xx：客户端错误类，表示请求包含语法错误或无法完成请求。 <ul><li>400 Bad Request：请求语法错误。</li><li>401 Unauthorized：请求要求身份验证。</li><li>403 Forbidden：服务器拒绝请求。</li><li>404 Not Found：服务器无法找到请求的资源。</li><li>405 Method Not Allowed：请求方法不被允许。</li><li>408 Request Timeout：请求超时。</li><li>429 Too Many Requests：请求过多。</li></ul></li><li>5xx：服务器错误类，表示服务器在处理请求的过程中发生了错误。 <ul><li>500 Internal Server Error：服务器内部错误。</li><li>502 Bad Gateway：网关错误。</li><li>503 Service Unavailable：服务不可用。</li><li>504 Gateway Timeout：网关超时。</li><li>511 Network Authentication Required：网络认证要求。</li></ul></li></ul></div><h2 id="_5-强缓存和协商缓存" tabindex="-1">5. 强缓存和协商缓存 <a class="header-anchor" href="#_5-强缓存和协商缓存" aria-label="Permalink to &quot;5. 强缓存和协商缓存&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">强缓存</p><p></p><ol><li>强缓存是指浏览器在请求资源时，先查看浏览器缓存中是否有缓存的副本，</li><li>如果有，则直接使用缓存副本，不再向服务器发送请求。</li></ol><ul><li><p>强缓存的优点：</p><ul><li>缓存命中率高，减少请求数，加快页面响应速度。</li></ul></li><li><p>强缓存的缺点：</p><ul><li>缓存过期时间无法设置，缓存时间一旦过期，则需要重新向服务器请求资源。</li><li>缓存无法更新，当缓存数据被更新时，浏览器并不会请求新的资源，而是继续使用旧的缓存。</li></ul></li></ul></div><div class="tip custom-block github-alert"><p class="custom-block-title">协商缓存</p><p></p><ol><li>浏览器在请求资源时，先向服务器发送请求，服务器根据请求头判断是否命中缓存，</li><li>如果命中，则返回 304 状态码，浏览器从缓存中获取资源，否则返回 200 状态码，并返回新的资源。</li></ol><ul><li><p>优点：</p><ul><li>缓存有效期可以设置，可以根据情况指定缓存过期时间。</li><li>缓存可以更新，当缓存数据被更新时，浏览器会请求新的资源，并更新缓存。</li></ul></li><li><p>缺点：</p><ul><li>缓存命中率低，增加了请求数，增加了服务器压力。</li><li>缓存无法命中，如果资源未被缓存，则需要向服务器请求资源。</li></ul></li></ul></div><h2 id="_6-socket-长连接和短连接" tabindex="-1">6. Socket 长连接和短连接 <a class="header-anchor" href="#_6-socket-长连接和短连接" aria-label="Permalink to &quot;6. Socket 长连接和短连接&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">长连接</p><p></p><ol><li>长连接：在一个 TCP 连接上可以发送多个 HTTP 请求，多个请求复用同一个 TCP 连接。</li><li>优点：</li></ol><ul><li><p>减少建立 TCP 连接的时间，减少了延迟。</p></li><li><p>同一个 TCP 连接可以发送多个请求，减少了网络流量。</p></li><li><p>缺点：</p><ul><li>服务器资源消耗较多，因为每个 TCP 连接都需要维护。</li><li>服务器需要维护大量的 TCP 连接，消耗系统资源。</li></ul></li></ul></div><div class="tip custom-block github-alert"><p class="custom-block-title">短连接</p><p></p><ol><li>短连接：在一个 TCP 连接上只发送一个 HTTP 请求，服务器处理完请求后，立即断开 TCP 连接。</li><li>优点：</li></ol><ul><li><p>减少了建立 TCP 连接的时间，减少了延迟。</p></li><li><p>减少了服务器资源消耗，因为每个 TCP 连接只处理一个请求。</p></li><li><p>缺点：</p><ul><li>同一个 TCP 连接上只能发送一个请求，不能发送多个请求。</li><li>服务器需要维护大量的 TCP 连接，消耗系统资源。</li></ul></li></ul></div><h2 id="_7-轮询、长轮询、sse、websocket" tabindex="-1">7. 轮询、长轮询、SSE、WebSocket <a class="header-anchor" href="#_7-轮询、长轮询、sse、websocket" aria-label="Permalink to &quot;7. 轮询、长轮询、SSE、WebSocket&quot;">​</a></h2><h3 id="_7-1、轮询" tabindex="-1">7.1、轮询 <a class="header-anchor" href="#_7-1、轮询" aria-label="Permalink to &quot;7.1、轮询&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">轮询</p><p></p><ol><li>指客户端不使用长连接，每隔一段时间就向服务器发送请求，询问是否有新数据。</li><li>优点：</li></ol><ul><li><p>实现简单：实现起来比较简单。</p></li><li><p>兼容性好： 所有浏览器和服务器都支持基本的 HTTP 请求。</p></li><li><p>缺点：</p><ul><li>无论服务器是否有新数据，都会立即响应（可能包含新数据，也可能为空）。</li><li>网络带宽： 大量请求（尤其是空响应）浪费带宽。</li><li>高延迟：数据更新只能在轮询间隔之后被客户端感知。间隔短则延迟低但开销大，间隔长则延迟高。</li><li>资源浪费巨大: 服务器端需要不断的向客户端推送数据，会消耗服务器资源。</li><li>服务器负载： 即使没有数据，服务器也要处理大量请求，消耗 CPU、内存和连接资源。</li><li>实时性差：客户端需要等待服务器返回数据，延迟较大。</li></ul></li></ul></div><h3 id="_7-2、长轮询" tabindex="-1">7.2、长轮询 <a class="header-anchor" href="#_7-2、长轮询" aria-label="Permalink to &quot;7.2、长轮询&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">7.2、长轮询</p><p></p><ol><li>客户端发起一个 HTTP 请求到服务器。服务器不会立即响应，而是保持连接打开直到：</li></ol><ul><li>有新数据时才向客户端发送响应。</li><li>超时时间到达时，服务器关闭连接。</li><li>客户端收到响应后，立即（或稍作延迟）发起下一个新的长轮询请求。</li></ul><ol start="2"><li>优点：</li></ol><ul><li><p>实时性好，客户端可以及时收到服务器的数据。</p></li><li><p>缺点：</p><ul><li>实现起来比较复杂。</li><li>服务器端需要不断的向客户端推送数据，会消耗服务器资源。</li></ul></li></ul></div><h3 id="_7-3、sse" tabindex="-1">7.3、SSE <a class="header-anchor" href="#_7-3、sse" aria-label="Permalink to &quot;7.3、SSE&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">SSE</p><p></p><ol><li>SSE（Server-Sent Event，服务器推送事件）是一种基于 HTTP 协议的轻量级的消息推送技术。</li><li>优点：</li></ol><ul><li><p>简单，实现起来比较简单。</p></li><li><p>实时性好，客户端可以及时收到服务器的数据。</p></li><li><p>缺点：</p><ul><li>兼容性不好，只有现代浏览器支持。</li><li>无法发送自定义消息。</li></ul></li></ul></div><h3 id="_7-4、websocket" tabindex="-1">7.4、WebSocket <a class="header-anchor" href="#_7-4、websocket" aria-label="Permalink to &quot;7.4、WebSocket&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">WebSocket</p><p></p><ol><li>WebSocket 是一种通信协议，它实现了浏览器与服务器全双工通信（full-duplex communication）。</li><li>优点：</li></ol><ul><li><p>建立在 TCP 协议之上，协议简单，易于实现。</p></li><li><p>双向通信，实时性好。</p></li><li><p>缺点：</p><ul><li>兼容性不好，只有现代浏览器支持。</li><li>服务器端需要支持 WebSocket 协议。</li></ul></li></ul></div>',25)]))}const b=i(a,[["render",c]]);export{T as __pageData,b as default};
